'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,d=2)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:d,maximumFractionDigits:d}).format(v||0);
const orderId=()=>crypto.randomUUID?crypto.randomUUID():[...crypto.getRandomValues(new Uint8Array(16))].map(n=>n.toString(16).padStart(2,'0')).join('');
const num=(v,d=2)=>Number(v||0).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=v=>(v>=0?'+':'')+num(v*100,2)+'%';
const paths={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',markets:'M3 17l5-7 5 4 8-11M3 21h18',research:'M9 3h6M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3M8 14h8',kronos:'M12 2l9 5v10l-9 5-9-5V7zM3 7l9 5 9-5M12 12v10M7 5l10 5v4',simulation:'M12 3a9 9 0 1 1-8.5 6M3 3v6h6M12 7v5l4 2',portfolio:'M3 8h18v13H3zM8 8V4h8v4M3 13h18M10 11v4h4v-4',execution:'M4 7h15l-4-4M20 17H5l4 4M19 7l-4 4M5 17l4-4',risk:'M12 2l8 4v6q0 7-8 10-8-3-8-10V6zM8 12l3 3 5-6',evidence:'M6 2h9l5 5v15H4V2zM14 2v6h6M8 12h8M8 16h8',integrations:'M8 3v5M16 3v5M5 8h14v4a7 7 0 0 1-14 0zM12 19v4'};
const views=[['overview','Overview'],['markets','Market scanner'],['research','Research lab'],['kronos','Kronos intelligence'],['simulation','Time machine'],['portfolio','Portfolio'],['execution','Execution'],['risk','Risk & controls'],['evidence','Evidence ledger'],['integrations','Integrations']];
const names={NVDA:'NVIDIA',AMAT:'Applied Materials',LRCX:'Lam Research',TER:'Teradyne',SPY:'S&P 500 ETF'};
let state,csrf='',selected='NVDA',range=70,route='overview',renderId=0,es=null,lastBacktest=null,lastSimulation=null,lastForecast=null,lastValuation=null,lastFilings=null,lastBroker=null,lastAgentJob=null,loading=false;
const icon=id=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[id]||paths.overview}" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
$('#nav').innerHTML=views.map(([id,title])=>`<a href="#${id}" data-view="${id}" aria-label="${title}">${icon(id)}<span>${title}</span>${id==='kronos'?'<em>AI</em>':''}</a>`).join('');
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className='visible'+(error?' error':'');clearTimeout(t.timer);t.timer=setTimeout(()=>t.className='',5500)}
async function api(url,body,method){const opts={method:method||(body!==undefined?'POST':'GET'),headers:{}};if(body!==undefined){opts.headers['Content-Type']='application/json';opts.headers['X-Aegis-CSRF']=csrf;opts.body=JSON.stringify(body)}const r=await fetch('/api'+url,opts);const result=await r.json();if(!r.ok){if(r.status===401){$('#login').classList.remove('hidden');es?.close()}const msg=typeof result.detail==='string'?result.detail:JSON.stringify(result.detail);throw Error(msg||'Request failed')}return result}
async function act(fn,message){if(loading)return;loading=true;document.body.setAttribute('aria-busy','true');try{const result=await fn();if(message)toast(message);await refresh();return result}catch(err){toast(err.message,true)}finally{loading=false;document.body.removeAttribute('aria-busy')}}
function badge(text,type=''){return `<span class="badge ${type}">${e(text)}</span>`}
function title(kicker,title,subtitle,actions=''){return `<div class="page-title"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function card(title,body,action='',cls=''){return `<section class="card ${cls}"><div class="card-head"><h2>${title}</h2>${action}</div>${body}</section>`}
function empty(title,body){return `<div class="empty"><span class="muted">◎</span><strong>${title}</strong>${body}</div>`}
function spark(values,color='#8cbe9a'){if(!values?.length)return '';let lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1;const pts=values.map((v,i)=>`${i*78/Math.max(1,values.length-1)},${21-(v-lo)/span*19}`).join(' ');return `<svg class="spark" viewBox="0 0 78 23" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.2"/></svg>`}
function metric(label,value,foot,accent='',trend){return `<div class="metric"><div class="metric-head"><span>${label}</span><span>↗</span></div><div class="metric-value ${accent}">${value}</div><div class="metric-foot">${foot}</div>${trend?`<div class="metric-spark">${spark(trend)}</div>`:''}</div>`}
function metrics(){const s=state.stats, fills=state.orders.filter(o=>o.filled_qty>0);return `<div class="metrics">${metric('Portfolio equity',money(s.equity),`<span class="${s.pnl>=0?'positive':'negative'}">${pct(s.return_pct/100)}</span> since session start`,'',state.equity_history.map(x=>x.equity))}${metric('Net paper P&L',money(s.pnl),`After modeled fees & slippage`,s.pnl>=0?'positive':'negative')}${metric('Gross exposure',num(s.gross_pct*100,1)+'%',`${money(s.gross,0)} across ${state.positions.length} positions`)}${metric('Execution evidence',String(fills.length).padStart(2,'0'),`${state.audit.events} hash-linked events · ${state.audit.valid?'verified':'check failed'}`)}</div>`}
function scannerTable(compact=false){return `<div class="table-wrap"><table><thead><tr><th>INSTRUMENT</th><th>PRICE</th><th>BAR CHANGE</th>${compact?'':'<th>REL. VOLUME</th>'}<th>24-BAR TREND</th><th>SIGNAL</th><th></th></tr></thead><tbody>${state.scanner.map(r=>`<tr><td><strong>${e(r.symbol)}</strong><small>${e(names[r.symbol]||'Imported instrument')}</small></td><td class="mono">${money(r.price)}</td><td class="mono ${r.change_pct>=0?'positive':'negative'}">${r.change_pct>=0?'+':''}${num(r.change_pct)}%</td>${compact?'':`<td class="mono">${num(r.relative_volume)}×</td>`}<td>${spark(r.series,r.change_pct>=0?'#75b59c':'#bb7c88')}</td><td>${badge(r.signal.action,r.signal.action==='BUY'?'green':r.signal.action==='SELL'?'red':'')} <span class="mono smalltext muted">${r.signal.score>0?'+':''}${num(r.signal.score)}</span></td><td><button class="subtle-action" data-action="select-symbol" data-symbol="${e(r.symbol)}" aria-label="Inspect ${e(r.symbol)}">↗</button></td></tr>`).join('')}</tbody></table></div>`}
function riskCard(){const s=state.stats,p=state.policy;let checks=[['Gross exposure',s.gross_pct,p.max_gross_pct],['Session loss',s.daily_loss_pct,p.max_daily_loss_pct],['Peak drawdown',s.drawdown_pct,p.max_drawdown_pct]];return card('Capital protection',`<div class="card-body"><div class="policy-status"><div class="ring">${state.halted?'!':'✓'}</div><div><strong>${state.halted?'Trading paused':'Within configured limits'}</strong><small>Deterministic pre-trade policy</small></div></div>${checks.map(([label,v,max])=>`<div class="progress-row"><span class="muted">${label}</span><span>${num(v*100,1)} <span class="muted">/ ${num(max*100,0)}%</span></span></div><div class="progress"><i style="width:${Math.min(100,v/max*100)}%;${v>=max?'background:var(--red)':''}"></i></div>`).join('')}<div class="mini-stat"><span>Maximum order</span><span>${money(p.max_order_notional,0)}</span></div><div class="mini-stat"><span>Execution environment</span><span class="positive">Paper only</span></div><button data-action="halt" class="${state.halted?'primary':'danger'} full section-gap">${state.halted?'Resume risk gate':'Halt new exposure'}</button></div><div class="risk-foot">Loss limits are controls, not guarantees. Reducing positions stays permitted.</div>`,badge(state.halted?'HALTED':'ARMED',state.halted?'red':'green'))}
function workflow(){const stages=[['⌁','Market data','markets'],['⌘','Signals','research'],['◈','Portfolio','portfolio'],['✓','Risk policy','risk'],['⇄','Execution','execution'],['▤','Evidence','evidence']];return card('Decision pipeline',`<div class="workflow">${stages.map(([ic,name,target],i)=>`${i?'<div class="workflow-line"></div>':''}<div class="workflow-node"><button class="node-icon" data-action="navigate" data-target="${target}" aria-label="Open ${name}">${ic}</button>${name}<small>${state.trace.length?'Traced':'Ready'}</small></div>`).join('')}</div><div class="chart-note">Native deterministic workers · structured outputs · no LLM agents claimed</div>`,badge(state.trace.length?'TRACE RECORDED':'CONNECTED','green'))}
function chartCard(){const r=state.scanner.find(x=>x.symbol===selected)||state.scanner[0];selected=r.symbol;return card('Market overview',`<div class="chart-toolbar"><div class="instrument"><div class="ticker-logo">${e(r.symbol[0])}</div><div><strong>${e(r.symbol)} <span class="muted">/ USD</span></strong><small>${e(names[r.symbol]||'Imported instrument')} · ${e(state.dataset.source)}</small></div></div><div class="instrument-price">${money(r.price)}<small class="${r.change_pct>=0?'positive':'negative'}">${r.change_pct>=0?'↗':'↘'} ${num(Math.abs(r.change_pct))}% latest bar</small></div></div><div class="chart-tabs">${[35,70,120,240].map(n=>`<button data-action="chart-range" data-count="${n}" class="${range===n?'active':''}">${n} bars</button>`).join('')}<span>OHLCV · drag crosshair / scroll to zoom</span></div><div class="chart-box" id="main-chart"><canvas aria-label="Interactive candlestick chart"></canvas><div class="chart-tip"></div></div><div class="chart-legend"><span><i class="legend-dot" style="background:#b6d58d"></i>Price candles</span><span><i class="legend-dot" style="background:#9aabe8"></i>SMA 8</span><span><i class="legend-dot" style="background:#caad7b"></i>SMA 21</span></div><div class="chart-note">Replay as of ${e(state.asof)} · prices are not a live quote</div>`,`<select id="chart-symbol" aria-label="Chart instrument" style="width:90px;padding:4px;font-size:10px;margin:0">${state.dataset.symbols.map(s=>`<option ${s===selected?'selected':''}>${e(s)}</option>`).join('')}</select>`)}
function activity(events){return card('Evidence stream',`<div class="event-list">${events.slice(0,5).map(r=>`<div class="event-row"><div class="event-icon">${r.kind.includes('reject')?'!':'↗'}</div><div><strong>${e(r.kind.replaceAll('.',' · '))}</strong><small>#${r.seq} · ${e(r.hash.slice(0,12))}</small></div><time>${e(r.wall_time.slice(11,19))}</time></div>`).join('')}</div>`,`<button class="subtle-action" data-action="navigate" data-target="evidence">View ledger ↗</button>`)}
function orderTable(orders=state.orders){return orders.length?`<div class="table-wrap"><table><thead><tr><th>ORDER / INSTRUMENT</th><th>SIDE</th><th>QTY / FILLED</th><th>FILL PRICE</th><th>STATUS</th><th>EVIDENCE / ACTION</th></tr></thead><tbody>${[...orders].reverse().slice(0,75).map(o=>`<tr><td><strong>${e(o.symbol)}</strong><small>${e(o.id)} · ${e(o.origin)}</small></td><td class="${o.side==='BUY'?'positive':'negative'}">${e(o.side)}</td><td class="mono">${o.qty} / ${o.filled_qty}</td><td class="mono">${o.fill_price?money(o.fill_price,4):'—'}</td><td>${badge(o.status,o.status==='FILLED'?'green':o.status==='REJECTED'?'red':'amber')}</td><td>${o.status==='QUEUED'?`<button data-action="cancel" data-id="${e(o.id)}">Cancel</button>`:`<span class="smalltext muted">${e(o.reasons?.join(', ')||'Fee '+money(o.fee))}</span>`}</td></tr>`).join('')}</tbody></table></div>`:empty('No orders in this session','Create a paper ticket or run the research cycle. Orders fill only after advancing replay.')}
function orderForm(){return card('Paper order ticket',`<form id="order-form" class="card-body"><div class="form-grid"><label>INSTRUMENT<select name="symbol">${state.dataset.symbols.map(s=>`<option ${s===selected?'selected':''}>${e(s)}</option>`).join('')}</select></label><label>SIDE<select name="side"><option>BUY</option><option>SELL</option></select></label><label>QUANTITY<input name="qty" type="number" min="1" step="1" value="2" required></label><label>ORDER TYPE<input value="Market · next replay open" readonly></label><label>STOP PRICE · OPTIONAL<input name="stop" type="number" min=".0001" step="any" placeholder="No protective stop"></label><label>TARGET PRICE · OPTIONAL<input name="target" type="number" min=".0001" step="any" placeholder="No profit target"></label></div><p class="subtext">Long-only. Available cash and pending orders are checked together. Fees and adverse spread apply at the next bar open.</p><button class="primary full" type="submit">Validate & queue paper order ↗</button></form>`,badge('NO REAL CAPITAL','amber'))}
async function refresh(){state=await api('/state');if(!state.dataset.symbols.includes(selected))selected=state.dataset.symbols[0];$('#source-footer').textContent=state.dataset.source==='SYNTHETIC'?'Synthetic fixture · no market feed':'Imported dataset · source not independently verified';$('#clock-footer').textContent='Replay '+state.asof+' · '+state.remaining_bars+' bars remaining';$('#alert-count').textContent=state.alerts.filter(a=>a.triggered).length;$('#connection').textContent=state.running?'Replay running':'Local engine connected';await render()}
async function render(){const id=++renderId;route=location.hash.slice(1)||'overview';if(!views.find(v=>v[0]===route))route='overview';const view=views.find(v=>v[0]===route);$('#crumb').textContent=view[1];$$('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.view===route));let html='',charts=[];
if(route==='overview'){
 const [market,audit]=await Promise.all([api('/market/'+selected),api('/audit')]);if(id!==renderId)return;
 html=title('THE RESEARCH ADVANTAGE','Trading intelligence, in focus.','One workspace. Every signal, decision and paper fill connected.',`<button data-action="step">Advance bar →</button><button class="primary" data-action="cycle">Run research cycle ↗</button>`)+metrics()+`<div class="grid-main"><div class="stack">${chartCard()}${card('Opportunity watchlist',scannerTable(true),badge(state.dataset.symbols.length+' INSTRUMENTS'))}${workflow()}</div><div class="stack">${riskCard()}${activity(audit.events)}${card('Replay control',`<div class="card-body"><div class="mini-stat"><span>Strategy</span><span>${e(state.strategy)}</span></div><div class="mini-stat"><span>Automation</span><span>${state.auto_orders?'Paper orders enabled':'Observe only'}</span></div><div class="mini-stat"><span>Bars remaining</span><span>${state.remaining_bars}</span></div><button class="full section-gap" data-action="play">${state.running?'Pause replay':'Start replay'}</button></div>`,badge(state.running?'RUNNING':'PAUSED',state.running?'green':''))}</div></div>`;
 charts.push(()=>candles($('#main-chart'),market.bars.slice(-range)));
}else if(route==='markets'){
 const market=await api('/market/'+selected);if(id!==renderId)return;
 html=title('DISCOVER / INSPECT / VALIDATE','Market scanner','Scores are deterministic indicators—not confidence probabilities.',`<button data-action="cycle" class="primary">Scan & propose ↗</button>`)+card('Research universe',scannerTable())+`<div class="grid-main section-gap"><div>${chartCard()}</div><div>${card('Price alert',`<form class="card-body" id="alert-form"><label>SYMBOL<select name="symbol">${state.dataset.symbols.map(s=>`<option ${s===selected?'selected':''}>${s}</option>`).join('')}</select></label><div class="form-grid"><label>DIRECTION<select name="direction"><option value="above">Crosses above</option><option value="below">Crosses below</option></select></label><label>PRICE<input name="price" type="number" step="any" min=".0001" value="${num(state.scanner.find(r=>r.symbol===selected)?.price*1.01).replaceAll(',','')}" required></label></div><button class="primary full">Create replay alert</button></form>`)}</div></div>`+card('Alert monitor',state.alerts.length?`<div class="card-body">${state.alerts.map(a=>`<div class="list-item"><div><strong>${e(a.symbol)} ${e(a.direction)} ${money(a.price)}</strong><p>${e(a.triggered_at||'Waiting for condition in replay')}</p></div>${badge(a.triggered?'TRIGGERED':'ARMED',a.triggered?'amber':'green')}</div>`).join('')}</div>`:empty('No price alerts','Create an alert above; conditions are evaluated as replay advances.'),'','section-gap');charts.push(()=>candles($('#main-chart'),market.bars.slice(-range)));
}else if(route==='research'){
 html=title('QUANTFORGE / RESEARCH WORKBENCH','Turn a hypothesis into evidence.','Cost-aware chronological replay with fixed parameters and an untouched evaluation window.')+`<div class="grid-main"><div class="stack">${card('Experiment configuration',`<form id="backtest-form" class="card-body"><div class="form-grid"><label>STRATEGY<select name="strategy"><option value="ensemble">Momentum + mean reversion</option><option value="trend">Moving-average trend</option><option value="reversion">Mean-reversion baseline</option></select></label><label>ONE-WAY COST BUDGET · BPS<input name="cost_bps" type="number" min="0" max="100" step=".5" value="6"></label></div><label class="inline-check"><input name="walk_forward" type="checkbox" checked> Include three chronological evaluation windows</label><p class="subtext">First 65% is history / warm-up; final 35% is the primary evaluation. No tuning on the test window. Parameters stay fixed. Synthetic data cannot establish investment performance.</p><button type="submit" class="primary">Run experiment ↗</button><span id="research-progress" class="muted smalltext"></span></form>`,badge('NEXT-OPEN EXECUTION','blue'))}<div id="backtest-result">${backtestHTML(lastBacktest)}</div></div><div class="stack">${card('Research protocol',`<div class="card-body"><div class="mini-stat"><span>Dataset</span><span>${e(state.dataset.source)}</span></div><div class="mini-stat"><span>Bars / instrument</span><span>${state.dataset.bars_per_symbol}</span></div><div class="mini-stat"><span>Feature access</span><span class="positive">Historical prefixes only</span></div><div class="mini-stat"><span>Costs</span><span>Spread + slip + commission</span></div><div class="mini-stat"><span>Reproducibility</span><span>Fixed data / rule hashes</span></div><div class="notice amber">No annualised Sharpe is shown without a validated sampling calendar. Descriptive results are not evidence of alpha.</div></div>`)}${card('Finance research agents (3-arm)',`<form id="agent-job-form" class="card-body"><div class="form-grid"><label>SYMBOL<select name="symbol">${state.dataset.symbols.map(s=>`<option ${s===selected?'selected':''}>${s}</option>`).join('')}</select></label><label>EVALUATION ARM<select name="arm"><option value="deterministic_baseline">Deterministic baseline</option><option value="retrieval_assisted_llm">Retrieval-assisted LLM</option><option value="verified_multi_role">Verified multi-role</option></select></label></div><button type="submit">Run bounded research job</button><pre id="agent-job-result" class="codebox">${e(lastAgentJob?JSON.stringify(lastAgentJob,null,2):'No research agent job run yet.')}</pre></form>`,badge('BOUNDED TOOLS'))}${valuationForm()}</div></div>`;if(lastBacktest)charts.push(()=>lineChart($('#backtest-chart'),lastBacktest.curve.map(x=>x.equity),lastBacktest.curve.map(x=>x.benchmark)));
}else if(route==='kronos'){
 const integration=await api('/integrations');if(id!==renderId)return;
 const k=integration.kronos;
 html=title('FOUNDATION-MODEL WORKSPACE','Kronos intelligence','Source-pinned model integration. Forecasts stay separate from execution authority.',badge(k.state,k.state==='READY'?'green':'amber'))+`<div class="kronos-hero"><div class="eyebrow">TOKENIZE THE MARKET. TEST THE FORECAST.</div><h2>From candlesticks to market representations.</h2><p>The real upstream tokenizer and autoregressive model are loaded only from verified artifacts. Independent sampled paths are preserved for analysis. No mock forecast is substituted.</p><div class="model-pipeline">${['OHLCV + amount','Context normalization','Binary spherical tokenizer','Hierarchical s1 / s2','Autoregressive sampling','Decode + validation'].map((v,i)=>`${i?'<span>→</span>':''}<div class="model-stage">${v}</div>`).join('')}</div></div><div class="grid-main"><div class="stack">${card('Forecast experiment',`<form id="forecast-form" class="card-body"><div class="form-grid"><label>INSTRUMENT<select name="symbol">${state.dataset.symbols.map(s=>`<option ${selected===s?'selected':''}>${s}</option>`).join('')}</select></label><label>HORIZON · BARS<input name="horizon" type="number" min="1" max="60" value="12"></label><label>INDEPENDENT SAMPLED PATHS<input name="samples" type="number" min="2" max="16" value="4"></label><label>RANDOM SEED<input name="seed" type="number" min="0" max="2147483647" value="26"></label></div><button class="primary" type="submit">Run real Kronos inference ↗</button><p class="subtext">Future inputs contain declared calendar timestamps only. Raw invalid OHLCV outputs are flagged—not silently repaired.</p></form>`)}<div id="forecast-result">${forecastHTML(lastForecast,k)}</div></div><div class="stack">${card('Artifact integrity',`<div class="card-body"><div class="mini-stat"><span>Model family</span><span>Kronos-mini</span></div><div class="mini-stat"><span>Source revision</span><span class="mono">${e((k.source_commit||'unverified').slice(0,12))}</span></div><div class="mini-stat"><span>Runtime</span><span>${e(k.device||'Not loaded')}</span></div><div class="mini-stat"><span>Checkpoint format</span><span>SafeTensors only</span></div><div class="mini-stat"><span>Fallback predictions</span><span class="positive">Never</span></div><p class="subtext">Install real weights from the official model repository on a connected host:</p><pre class="codebox">python scripts/install_kronos.py
python scripts/kronos_smoke.py</pre><p class="subtext">The installer pins the source commit and model revisions, records SHA-256 checksums, and writes the artifact lock.</p></div>`)}${card('Interpretation boundaries',`<div class="card-body"><p class="subtext">Sample quantiles are not calibrated confidence intervals. A valid model output does not establish a profitable strategy.</p><p class="subtext">Traded amount is an upstream proxy when absent from the dataset. Hardware-specific inference differences must be recorded.</p><div class="notice amber">Forecast output is research evidence only. It cannot send an order or alter the risk policy.</div></div>`)}</div></div>`;if(lastForecast)charts.push(()=>fanChart($('#forecast-chart'),lastForecast.bands));
}else if(route==='simulation'){
 html=title('SCENARIO EXPLORATION','The time machine','Explore plausible paths from historical blocks—not promises about future prices.')+`<div class="grid-main"><div class="stack">${card('Scenario generator',`<form class="card-body" id="simulation-form"><div class="form-grid"><label>INSTRUMENT<select name="symbol">${state.dataset.symbols.map(s=>`<option ${selected===s?'selected':''}>${s}</option>`).join('')}</select></label><label>SIMULATED PATHS<select name="trials"><option>1000</option><option>2500</option><option>10000</option></select></label><label>HORIZON · BARS<input name="horizon" type="number" min="2" max="120" value="30"></label><label>RANDOM SEED<input name="seed" type="number" min="0" max="2147483647" value="26"></label><label>STOP DISTANCE · %<input name="stop_pct" type="number" min=".1" max="49" step=".1" value="2"></label><label>TARGET DISTANCE · %<input name="target_pct" type="number" min=".1" max="99" step=".1" value="4"></label></div><button class="primary" type="submit">Generate scenarios ↗</button></form>`,badge('MOVING-BLOCK BOOTSTRAP','blue'))}<div id="simulation-result">${simulationHTML(lastSimulation)}</div></div><div class="stack">${card('What this measures',`<div class="card-body"><div class="mini-stat"><span>Sampling</span><span>Contiguous return blocks</span></div><div class="mini-stat"><span>Block length</span><span>5 observations</span></div><div class="mini-stat"><span>Quantiles</span><span>5th / median / 95th</span></div><div class="mini-stat"><span>Net cost deduction</span><span>7 bps total per path</span></div><div class="notice amber">Barrier-hit frequencies use closing prices. They are not calibrated forecast probabilities. Unseen crises and market gaps are not guaranteed to appear.</div><p class="subtext">Terminal returns are buy-and-hold scenario outcomes, not a simulated stop/target trading policy.</p></div>`)}${card('Reproducibility',`<div class="card-body"><p class="subtext">Every simulation records its dataset hash, information timestamp, sample count, horizon and seed. Re-running the same configuration reproduces the same empirical paths.</p><button data-action="navigate" data-target="evidence" class="full">Inspect evidence →</button></div>`)}</div></div>`;if(lastSimulation)charts.push(()=>fanChart($('#simulation-chart'),lastSimulation.bands));
}else if(route==='portfolio'){
 const corr=await api('/correlation');if(id!==renderId)return;
 html=title('CAPITAL / EXPOSURE / ATTRIBUTION','Portfolio command','Positions and cash reconcile to modeled fills. Values follow the active replay clock.')+metrics()+card('Open positions',state.positions.length?`<div class="table-wrap"><table><thead><tr><th>INSTRUMENT</th><th>QUANTITY</th><th>AVERAGE COST</th><th>MARK</th><th>MARKET VALUE</th><th>UNREALISED P&L</th></tr></thead><tbody>${state.positions.map(p=>`<tr><td><strong>${e(p.symbol)}</strong></td><td>${p.qty}</td><td>${money(p.average,4)}</td><td>${money(p.mark)}</td><td>${money(p.value)}</td><td class="${p.unrealized>=0?'positive':'negative'}">${money(p.unrealized)}</td></tr>`).join('')}</tbody></table></div>`:empty('No open positions','Run a research cycle and advance one bar, or create a paper order.'))+`<div class="grid-two section-gap">${card('Equity history',`<div class="chart-box" id="equity-chart"><canvas></canvas></div><div class="chart-note">Mark-to-market equity; unrealised positions remain open.</div>`)}${card('Return correlations',heatmap(corr),badge(corr.observations+' OBSERVATIONS'))}</div>`;charts.push(()=>lineChart($('#equity-chart'),state.equity_history.map(x=>x.equity)));
}else if(route==='execution'){
 html=title('CONTROLLED PAPER EXECUTION','Every order. Every outcome.','Orders queue now and execute at the next replay open, subject to risk revalidation.',`<button data-action="step" class="primary">Advance & process orders →</button>`)+`<div class="grid-main"><div>${card('Order blotter',orderTable(),badge(state.orders.length+' ORDERS'))}</div><div class="stack">${orderForm()}${card('Fill model',`<div class="card-body"><div class="mini-stat"><span>Commission / side</span><span>${state.policy.commission_bps} bps</span></div><div class="mini-stat"><span>Half spread</span><span>${state.policy.half_spread_bps} bps</span></div><div class="mini-stat"><span>Adverse slippage</span><span>${state.policy.slippage_bps} bps</span></div><div class="mini-stat"><span>Volume participation</span><span>${num(state.policy.max_participation*100,1)}%</span></div><p class="subtext">Remainders cancel after a modeled partial fill. The simulator does not reproduce exchange queue priority.</p></div>`)}</div></div>`;
}else if(route==='risk'){
 const fields=[['max_order_notional','MAX ORDER NOTIONAL · USD',1],['max_position_pct','MAX SINGLE POSITION · FRACTION',.01],['max_gross_pct','MAX GROSS EXPOSURE · FRACTION',.01],['max_daily_loss_pct','MAX SESSION LOSS · FRACTION',.001],['max_drawdown_pct','MAX DRAWDOWN · FRACTION',.001],['max_participation','MAX VOLUME PARTICIPATION',.001],['commission_bps','COMMISSION · BPS',.1],['half_spread_bps','HALF SPREAD · BPS',.1],['slippage_bps','SLIPPAGE · BPS',.1]];
 html=title('QUANTSHIELD / TRADING CONTROLS','Risk is a boundary, not a suggestion.','Native simulation controls. No claim of certification against a funded-account provider’s current rules.')+`<div class="grid-main"><div class="stack">${card('Account policy',`<form id="policy-form" class="card-body"><div class="form-grid">${fields.map(([key,label,step])=>`<label>${label}<input name="${key}" type="number" step="${step}" min="0" value="${state.policy[key]}"></label>`).join('')}</div><div class="notice amber">Pause replay and cancel queued orders before changing policy. Loss reference resets on UTC session dates; this is not an official FTMO rules implementation.</div><button class="primary">Validate & save policy</button></form>`)}${card('Automation policy',`<form id="automation-form" class="card-body"><div class="form-grid"><label>STRATEGY<select name="strategy">${['ensemble','trend','reversion'].map(s=>`<option ${state.strategy===s?'selected':''}>${s}</option>`).join('')}</select></label><label>REPLAY INTERVAL · SECONDS<input name="interval_seconds" type="number" min=".5" max="30" step=".5" value="${state.interval_seconds}"></label></div><label class="inline-check"><input name="auto_orders" type="checkbox" ${state.auto_orders?'checked':''}>Allow deterministic strategy to submit local paper orders</label><button class="primary">Save automation settings</button><p class="subtext">The clock is separate: use Start replay after configuring. Shutdown pauses the clock. No external order submission is implemented.</p></form>`)}</div><div class="stack">${riskCard()}${card('Failure behavior',`<div class="card-body"><div class="list-item"><div><strong>Fail closed</strong><p>Unknown symbols, non-finite values and invalid data are rejected.</p></div></div><div class="list-item"><div><strong>Atomic account updates</strong><p>Cash, positions, order state and evidence commit together.</p></div></div><div class="list-item"><div><strong>Risk-reducing exits</strong><p>A halt blocks new exposure without disabling long-position exits.</p></div></div></div>`)}</div></div>`;
}else if(route==='evidence'){
 const audit=await api('/audit');if(id!==renderId)return;
 html=title('REPLAYABLE DECISIONS / VERIFIABLE RECORDS','Evidence, without the guesswork.','Hash-linked events and deterministic replay. Local evidence is tamper-evident, not immutable.',`<button data-action="refresh">Verify chain</button><button data-action="export-audit" class="primary">Export evidence ↗</button>`)+`<div class="health-grid"><div class="health-box"><span class="muted smalltext">CHAIN VALIDATION</span><strong class="${audit.verification.valid?'positive':'negative'}">${audit.verification.valid?'Verified':'Failed'}</strong><small class="muted">Recomputed event hashes</small></div><div class="health-box"><span class="muted smalltext">EVENTS</span><strong>${audit.verification.events}</strong><small class="muted">${audit.reconciliation?.valid?'Cash & positions reconciled':'Reconciliation requires review'}</small></div><div class="health-box"><span class="muted smalltext">DATASET ID</span><strong class="mono" style="font-size:16px;margin:9px 0">${e(state.dataset.id)}</strong><small class="muted">Content-derived identifier</small></div></div><div class="notice amber">Export the chain anchor to an independent store. An administrator with database access can rewrite the ledger and its local head.</div>`+card('Event ledger',`<div class="table-wrap"><table><thead><tr><th>SEQ</th><th>EVENT</th><th>WALL CLOCK · UTC</th><th>HASH</th><th>PAYLOAD</th></tr></thead><tbody>${audit.events.map(r=>`<tr><td class="mono">${r.seq}</td><td>${badge(r.kind,r.kind.includes('reject')?'red':r.kind.includes('fill')?'green':'')}</td><td class="mono smalltext">${e(r.wall_time.slice(0,19))}</td><td class="mono smalltext">${e(r.hash.slice(0,20))}…</td><td><button data-action="event-detail" data-seq="${r.seq}" class="subtle-action">Inspect ↗</button></td></tr>`).join('')}</tbody></table></div>`)+card('Selected event',`<pre id="event-detail" class="codebox">Select an event to inspect its recorded payload.</pre>`,'','section-gap');window._events=audit.events;
}else if(route==='integrations'){
 const [integration,feedStatus,llmStatus]=await Promise.all([api('/integrations'),api('/market/feed/status'),api('/llm/status')]);if(id!==renderId)return;
 const provEntries=Object.entries(integration.providers||{});
 html=title('DATA / MODELS / CONNECTIVITY','A connected, honest workspace.','External dependencies are explicit. No unavailable service is represented as working.')+`<div class="grid-main"><div class="stack">${card('Provider qualification matrix',`<div class="table-wrap"><table><thead><tr><th>PROVIDER</th><th>CONFIGURED</th><th>AUTH</th><th>FRESH</th><th>QUALIFIED</th></tr></thead><tbody>${provEntries.map(([name,p])=>`<tr><td><strong>${e(name)}</strong></td><td>${p.configured?'Yes':'No'}</td><td>${e(String(p.authenticated))}</td><td>${p.fresh?'Yes':'No'}</td><td>${badge(p.qualified?'QUALIFIED':'UNQUALIFIED',p.qualified?'green':'amber')}</td></tr>`).join('')}</tbody></table></div>`,badge((integration.settings?.data_mode||'synthetic').toUpperCase()+' · '+(integration.settings?.execution_mode||'paper_local').toUpperCase(),'blue'))}${card('Connection registry',`<div class="card-body">${integration.connectors.map(c=>`<div class="list-item"><div><strong>${e(c.name)}</strong><p>${e(c.role)}</p></div>${badge(c.state,c.state==='READY'?'green':'amber')}</div>`).join('')}<div class="list-item"><div><strong>Kronos model runtime</strong><p>Verified source and weight artifacts; no hidden fallback.</p></div>${badge(integration.kronos.state,integration.kronos.state==='READY'?'green':'amber')}</div><div class="list-item"><div><strong>OpenRouter LLM gateway</strong><p>Key: ${e(llmStatus.key_state)} · Paid calls: ${llmStatus.paid_calls_authorized?'Authorized':'Disabled'}</p></div>${badge(llmStatus.models_lock?.status||'UNQUALIFIED',llmStatus.paid_calls_authorized?'blue':'amber')}</div><div class="list-item"><div><strong>Market feed supervisor (${e(feedStatus.feed)} · ${e(feedStatus.coverage)})</strong><p>Session: ${e(feedStatus.session)} · Queue: ${feedStatus.queue_depth}</p></div>${badge(feedStatus.state,feedStatus.state==='RECEIVING'?'green':'amber')}</div></div>`)}${card('Point-in-time dataset',`<div class="card-body"><div class="mini-stat"><span>Active source</span><span>${e(state.dataset.source)}</span></div><div class="mini-stat"><span>Observations</span><span>${state.dataset.rows}</span></div><div class="mini-stat"><span>Period</span><span>${e(state.dataset.start.slice(0,10))} → ${e(state.dataset.end.slice(0,10))}</span></div><p class="subtext">Required CSV fields: symbol, timestamp, available_at, open, high, low, close, volume. All instruments need aligned timestamps and at least 65 bars. Import starts a new paper session.</p><div class="actions"><button data-action="download-data">Export current CSV</button><button data-action="import-data" class="primary">Import CSV ↗</button><input type="file" id="csv-upload" accept=".csv,text/csv" class="hidden"></div><div class="notice amber">Corporate actions, survivorship and historical availability are not independently established. Corporate-action event rows are rejected rather than silently mishandled.</div></div>`)}${card('SEC filing research',`<form class="card-body" id="sec-form"><div class="form-grid"><label>COMPANY CIK<input name="cik" value="1045810" inputmode="numeric" pattern="[0-9]{1,10}"></label><label>ACCESS<input readonly value="Read only · requires SEC_USER_AGENT"></label></div><button>Retrieve public filings</button><pre id="sec-result" class="codebox">${e(lastFilings?JSON.stringify(lastFilings,null,2):'No external query has been run.')}</pre></form>`)}${card('Paper broker reconciliation',`<div class="card-body"><p class="subtext">The Alpaca connector reads the configured paper account and recent orders. It cannot submit orders. Credentials stay in environment variables.</p><button data-action="broker-read">Read configured paper account</button><pre id="broker-result" class="codebox">${e(lastBroker?JSON.stringify(lastBroker,null,2):'Not connected.')}</pre></div>`)}</div><div class="stack">${card('Local deployment',`<div class="card-body"><div class="mini-stat"><span>Storage</span><span>SQLite / WAL</span></div><div class="mini-stat"><span>Workspace authentication</span><span>Token + session cookie</span></div><div class="mini-stat"><span>CSRF / origin checks</span><span class="positive">Enabled</span></div><div class="mini-stat"><span>Execution authority</span><span>${e(integration.settings?.execution_mode||'paper_local')}</span></div><div class="mini-stat"><span>Live money</span><span class="positive">Disabled</span></div><div class="notice amber">Single-operator local release. Not multi-tenant or approved for public Internet deployment.</div></div>`)}${card('Session management',`<div class="card-body"><p class="subtext">Start a fresh paper account with the same active dataset. Existing evidence is retained and a reset event is appended.</p><button class="danger full" data-action="reset">Reset paper session</button></div>`)}</div></div>`;
}
if(id!==renderId)return;$('#app').innerHTML=html;charts.forEach(f=>f());bindForms();}
function backtestHTML(r){if(!r)return card('Experiment results',empty('Ready to test a hypothesis','Run an experiment to inspect net returns, drawdowns, turnover, fills and chronological windows.'));return `<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Net test return',pct(r.net_return),'After configured costs',r.net_return>=0?'positive':'negative')}${metric('Maximum drawdown',num(r.max_drawdown*100)+'%','Observed test-window peak loss')}${metric('Filled orders',r.fills,'Fees '+money(r.fees))}</div>`+card('Out-of-sample equity',`<div class="chart-box" id="backtest-chart"><canvas></canvas></div><div class="chart-legend"><span class="positive">● Strategy</span><span class="muted">● ${e(r.benchmark)}</span></div><div class="chart-note">${e(r.window.start)} → ${e(r.window.end)} · ${e(r.dataset.source)}</div>`)+card('Chronological windows',`<div class="table-wrap"><table><thead><tr><th>WINDOW</th><th>NET RETURN</th><th>DRAWDOWN</th><th>FILLS</th></tr></thead><tbody>${r.folds.map((f,i)=>`<tr><td>Window ${i+1}</td><td class="${f.net_return>=0?'positive':'negative'}">${pct(f.net_return)}</td><td>${num(f.max_drawdown*100)}%</td><td>${f.fills}</td></tr>`).join('')}</tbody></table></div><div class="chart-note">${e(r.protocol.fold_interpretation)}</div>`,'','section-gap')}
function valuationResult(r){return !r?'':`<div class="mini-stat"><span>Estimated per share</span><strong>${money(r.per_share)}</strong></div><div class="mini-stat"><span>Enterprise value</span><strong>${money(r.enterprise_value)}</strong></div><div class="mini-stat"><span>Terminal value share</span><strong>${num(r.terminal_share*100)}%</strong></div>`}
function valuationForm(){return card('Valuation calculator',`<form id="dcf-form" class="card-body"><p class="subtext">Illustrative user-entered assumptions, not verified company financials. Use consistent currency and share units.</p><div class="form-grid">${[['fcf','FREE CASH FLOW',100],['growth','GROWTH · FRACTION',.05],['discount','DISCOUNT RATE',.1],['terminal_growth','TERMINAL GROWTH',.02],['years','YEARS',5],['shares','SHARES',10],['debt','DEBT',0],['cash','CASH',0]].map(([name,label,value])=>`<label>${label}<input type="number" name="${name}" value="${value}" step="any" required></label>`).join('')}</div><button class="full">Calculate DCF</button><div id="dcf-result" class="subtext section-gap">${valuationResult(lastValuation)}</div></form>`)}
function simulationHTML(r){if(!r)return card('Scenario distribution',empty('Explore the range, not one prediction','Generate a reproducible ensemble of paths from the available history.'));return `<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Target first',num(r.target_first*100,1)+'%','Empirical scenario frequency')}${metric('Stop first',num(r.stop_first*100,1)+'%','Close-only barrier observations')}${metric('Unresolved',num(r.unresolved*100,1)+'%','No barrier hit within horizon')}</div>`+card('Price path envelope',`<div class="chart-box" id="simulation-chart"><canvas></canvas></div><div class="chart-legend"><span>● Median path</span><span>5–95% empirical sample envelope</span></div><div class="chart-note">${r.trials} paths · seed ${r.seed} · ${r.history_bars} historical bars · not calibrated</div>`)+`<div class="notice amber">Mean terminal net return ${pct(r.mean_net_return)}. Worst 5% mean loss: ${num(r.expected_shortfall_loss*100)}%. Results depend on the assumed historical sample and cost deduction.</div>`}
function forecastHTML(r,k){if(!r)return card('Model output',empty(k.state==='NOT_INSTALLED'?'Real model artifacts required':'No forecast run in this view',e(k.reason||'Run inference to inspect independently sampled future paths.')));return card('Kronos sampled paths',`<div class="chart-box" id="forecast-chart"><canvas></canvas></div><div class="chart-note">${e(r.model)} · ${r.samples} samples · ${num(r.latency_seconds)} s · ${r.ohlcv_violations} invalid OHLCV records</div><div class="card-body"><span class="badge ${r.ohlcv_valid?'green':'red'}">${r.ohlcv_valid?'OUTPUT SHAPE VALID':'INVALID OHLCV FLAGGED'}</span><p class="subtext">This validity label is not trade approval or a profitability claim. Forecast provenance is preserved in the evidence ledger.</p></div>`)}
function heatmap(c){return `<div class="card-body"><div class="heatmap" style="grid-template-columns:50px repeat(${c.symbols.length},1fr)"><div></div>${c.symbols.map(s=>`<div class="heatmap-label">${e(s)}</div>`).join('')}${c.symbols.map((s,i)=>`<div class="heatmap-label">${e(s)}</div>${c.matrix[i].map(v=>`<div class="heatmap-cell" style="background:${v>=0?`rgba(105,170,127,${.08+Math.abs(v)*.40})`:`rgba(191,100,122,${.08+Math.abs(v)*.4})`}">${num(v)}</div>`).join('')}`).join('')}</div></div>`}
function bindForms(){
 const bind=(id,fn)=>{const f=$(id);if(f)f.onsubmit=ev=>{ev.preventDefault();act(()=>fn(new FormData(f)))}};
 bind('#order-form',async f=>{const out=await api('/orders',{symbol:f.get('symbol'),side:f.get('side'),qty:Number(f.get('qty')),client_id:orderId(),stop:f.get('stop')?Number(f.get('stop')):null,target:f.get('target')?Number(f.get('target')):null});toast(out.status==='REJECTED'?'Order blocked: '+out.reasons.join(', '):'Paper order queued for the next open',out.status==='REJECTED')});
 bind('#backtest-form',async f=>{const el=$('#research-progress');if(el)el.textContent='  Running chronological replay…';lastBacktest=await api('/backtests',{strategy:f.get('strategy'),cost_bps:Number(f.get('cost_bps')),walk_forward:f.has('walk_forward')});toast('Backtest saved with reproducible evidence')});
 bind('#simulation-form',async f=>{const body=Object.fromEntries(f);for(const k of ['trials','horizon','seed','stop_pct','target_pct'])body[k]=Number(body[k]);body.stop_pct/=100;body.target_pct/=100;lastSimulation=await api('/simulations',body);toast('Scenario paths generated and recorded')});
 bind('#forecast-form',async f=>{lastForecast=await api('/forecasts',{symbol:f.get('symbol'),horizon:+f.get('horizon'),samples:+f.get('samples'),seed:+f.get('seed')});toast('Real Kronos forecast recorded')});
 bind('#policy-form',async f=>{const body=Object.fromEntries([...f].map(([k,v])=>[k,Number(v)]));await api('/risk/policy',body);toast('Risk policy validated and saved')});
 bind('#automation-form',async f=>{await api('/config',{strategy:f.get('strategy'),interval_seconds:+f.get('interval_seconds'),auto_orders:f.has('auto_orders')});toast('Automation configuration saved')});
 bind('#alert-form',async f=>{await api('/alerts',{symbol:f.get('symbol'),price:+f.get('price'),direction:f.get('direction')});toast('Replay price alert created')});
 // Result panels use independent requests to preserve calculated output across refresh.
 const dcf=$('#dcf-form');if(dcf)dcf.onsubmit=async ev=>{ev.preventDefault();try{const body=Object.fromEntries([...new FormData(dcf)].map(([k,v])=>[k,+v]));const r=await api('/valuation',body);lastValuation=r;if($('#dcf-result'))$('#dcf-result').innerHTML=valuationResult(r)}catch(err){toast(err.message,true)}};
 const sec=$('#sec-form');if(sec)sec.onsubmit=async ev=>{ev.preventDefault();$('#sec-result').textContent='Retrieving official filing metadata…';try{lastFilings=await api('/filings/'+new FormData(sec).get('cik'));if($('#sec-result'))$('#sec-result').textContent=JSON.stringify(lastFilings,null,2)}catch(err){$('#sec-result').textContent=err.message;toast(err.message,true)}};
 const aj=$('#agent-job-form');if(aj)aj.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(aj);try{lastAgentJob=await api('/agents/jobs',{symbol:fd.get('symbol'),arm:fd.get('arm')});if($('#agent-job-result'))$('#agent-job-result').textContent=JSON.stringify(lastAgentJob,null,2);toast('Research agent job completed: '+lastAgentJob.status)}catch(err){toast(err.message,true)}};
 if($('#chart-symbol'))$('#chart-symbol').onchange=ev=>{selected=ev.target.value;render()};
 if($('#csv-upload'))$('#csv-upload').onchange=ev=>{const file=ev.target.files[0];if(!file)return;if(file.size>8e6){toast('CSV exceeds 8 MB',true);return}if(confirm('Import this dataset and reset the paper portfolio? Existing evidence is preserved.'))act(async()=>{await api('/data/import',{label:file.name,csv_text:await file.text(),confirm_reset:true});lastBacktest=null;lastSimulation=null;lastForecast=null},'Dataset validated and imported')};
}
$('#app').addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='navigate'){location.hash=b.dataset.target;return}if(a==='select-symbol'){selected=b.dataset.symbol;if(route!=='markets')location.hash='markets';else render();return}if(a==='chart-range'){range=+b.dataset.count;render();return}
 if(a==='event-detail'){$('#event-detail').textContent=JSON.stringify(window._events.find(x=>x.seq===+b.dataset.seq),null,2);$('#event-detail').scrollIntoView({behavior:'smooth',block:'nearest'});return}
 if(a==='import-data'){$('#csv-upload').click();return}if(a==='download-data'){download('/api/data/export','aegis_dataset.csv');return}if(a==='export-audit'){download('/api/audit/export','aegis_evidence.json');return}
 if(a==='broker-read'){try{lastBroker=await api('/broker/paper-account');if($('#broker-result'))$('#broker-result').textContent=JSON.stringify(lastBroker,null,2)}catch(err){$('#broker-result').textContent=err.message;toast(err.message,true)}return}
 if(a==='reset'){if(confirm('Reset the paper account to $100,000? Evidence stays in the ledger.'))act(()=>api('/reset',{confirm:'RESET PAPER SESSION',capital:100000}),'New paper session started');return}
 const operations={step:()=>api('/replay/step',{count:1}),cycle:()=>api('/research/cycle',{}),halt:()=>api('/risk/halt',{enabled:!state.halted}),play:()=>api('/config',{running:!state.running}),cancel:()=>api('/orders/'+b.dataset.id+'/cancel',{}),refresh:()=>Promise.resolve()};if(operations[a])act(operations[a],a==='cycle'?'Research cycle traced; proposals sent through policy':a==='step'?'Replay advanced':'Updated');
});
async function download(url,name){try{const r=await fetch(url);if(!r.ok)throw Error('Export failed');const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}catch(err){toast(err.message,true)}}
function setupCanvas(box){if(!box)return null;const canvas=box.querySelector('canvas'),rect=box.getBoundingClientRect(),ratio=window.devicePixelRatio||1;canvas.width=rect.width*ratio;canvas.height=rect.height*ratio;const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);return {canvas,ctx,w:rect.width,h:rect.height}}
function grid(ctx,w,h,lo,hi,left=12,right=65){ctx.clearRect(0,0,w,h);ctx.font='9px Consolas,monospace';ctx.textBaseline='middle';for(let j=0;j<5;j++){const y=16+j*(h-54)/4;ctx.strokeStyle='#202b3666';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle='#617386';ctx.fillText(num(hi-(hi-lo)*j/4),w-right+9,y)}return {x:i=>left+i*(w-left-right),y:v=>16+(hi-v)/(hi-lo||1)*(h-54),pw:w-left-right}}
function candles(box,bars){if(!box||!bars.length)return;const {canvas,ctx,w,h}=setupCanvas(box);const lows=bars.map(b=>b.low),highs=bars.map(b=>b.high);let lo=Math.min(...lows),hi=Math.max(...highs),pad=(hi-lo)*.12||1;lo-=pad;hi+=pad;const gh=h-38;const g=grid(ctx,w,gh,lo,hi);const dx=g.pw/bars.length,cw=Math.max(2,dx*.56);let vmax=Math.max(...bars.map(b=>b.volume));const draw=()=>{grid(ctx,w,gh,lo,hi);bars.forEach((b,i)=>{const x=g.x((i+.5)/bars.length),color=b.close>=b.open?'#9bbf8c':'#b87581';ctx.strokeStyle=color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,g.y(b.high));ctx.lineTo(x,g.y(b.low));ctx.stroke();ctx.fillStyle=color;ctx.fillRect(x-cw/2,Math.min(g.y(b.open),g.y(b.close)),cw,Math.max(1,Math.abs(g.y(b.open)-g.y(b.close))));ctx.fillStyle=b.close>=b.open?'#63876355':'#9f617344';ctx.fillRect(x-cw/2,h-25-b.volume/vmax*26,cw,b.volume/vmax*26)});[8,21].forEach((win,n)=>{ctx.strokeStyle=n?'#bca47a':'#8699d4';ctx.lineWidth=1;ctx.beginPath();let begun=false;bars.forEach((b,i)=>{if(i<win-1)return;const avg=bars.slice(i-win+1,i+1).reduce((a,v)=>a+v.close,0)/win;const x=g.x((i+.5)/bars.length),y=g.y(avg);begun?ctx.lineTo(x,y):ctx.moveTo(x,y);begun=true});ctx.stroke()});ctx.font='8px Consolas,monospace';ctx.fillStyle='#596b7e';[0,.25,.5,.75,1].forEach(f=>{const i=Math.min(bars.length-1,Math.floor((bars.length-1)*f));ctx.fillText(bars[i].timestamp.slice(11,16),g.x(f)*.95+4,h-7)});const last=bars.at(-1).close,y=g.y(last);ctx.setLineDash([3,4]);ctx.strokeStyle='#a8ce8255';ctx.beginPath();ctx.moveTo(12,y);ctx.lineTo(w-66,y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#abc98e';ctx.fillRect(w-63,y-9,59,18);ctx.fillStyle='#142218';ctx.font='9px Consolas,monospace';ctx.fillText(num(last),w-58,y)};draw();const tip=box.querySelector('.chart-tip');canvas.onpointermove=ev=>{draw();const rect=canvas.getBoundingClientRect(),x=ev.clientX-rect.left,i=Math.max(0,Math.min(bars.length-1,Math.floor((x-12)/g.pw*bars.length))),b=bars[i];ctx.setLineDash([3,4]);ctx.strokeStyle='#8c9bab66';ctx.beginPath();ctx.moveTo(x,10);ctx.lineTo(x,h-27);ctx.stroke();ctx.setLineDash([]);if(tip){tip.style.display='block';tip.textContent=`${b.timestamp.slice(0,16)}  O ${num(b.open)}  H ${num(b.high)}  L ${num(b.low)}  C ${num(b.close)}`}};canvas.onpointerleave=()=>{draw();if(tip)tip.style.display='none'};canvas.onwheel=ev=>{ev.preventDefault();range=Math.max(25,Math.min(240,range+(ev.deltaY>0?15:-15)));clearTimeout(canvas.zoom);canvas.zoom=setTimeout(()=>render(),80)};}
function lineChart(box,values,compare){if(!box)return;const {ctx,w,h}=setupCanvas(box);if(values.length<2){grid(ctx,w,h,0,1);ctx.fillStyle='#7c90a4';ctx.font='12px sans-serif';ctx.fillText('Advance replay to build an equity curve.',25,h/2);return}const all=values.concat(compare||[]),lo=Math.min(...all),hi=Math.max(...all),pad=(hi-lo)*.15||1,g=grid(ctx,w,h,lo-pad,hi+pad);[compare,values].forEach((arr,k)=>{if(!arr)return;ctx.beginPath();arr.forEach((v,i)=>i?ctx.lineTo(g.x(i/(arr.length-1)),g.y(v)):ctx.moveTo(g.x(0),g.y(v)));if(k){ctx.lineTo(g.x(1),h-38);ctx.lineTo(g.x(0),h-38);ctx.closePath();const grad=ctx.createLinearGradient(0,10,0,h);grad.addColorStop(0,'#a4d88a22');grad.addColorStop(1,'#a4d88a00');ctx.fillStyle=grad;ctx.fill();ctx.beginPath();arr.forEach((v,i)=>i?ctx.lineTo(g.x(i/(arr.length-1)),g.y(v)):ctx.moveTo(g.x(0),g.y(v)))}ctx.strokeStyle=k?'#afd68b':'#7c8da0';ctx.lineWidth=k?1.8:1;ctx.stroke()});}
function fanChart(box,bands){if(!box||!bands.length)return;const {ctx,w,h}=setupCanvas(box),lo=Math.min(...bands.map(b=>b.low)),hi=Math.max(...bands.map(b=>b.high)),pad=(hi-lo)*.1||1,g=grid(ctx,w,h,lo-pad,hi+pad);ctx.beginPath();bands.forEach((b,i)=>i?ctx.lineTo(g.x(i/(bands.length-1)),g.y(b.high)):ctx.moveTo(g.x(0),g.y(b.high)));[...bands].reverse().forEach((b,j)=>ctx.lineTo(g.x((bands.length-1-j)/(bands.length-1)),g.y(b.low)));ctx.closePath();ctx.fillStyle='#a3cf8830';ctx.fill();ctx.strokeStyle='#a3cf8866';ctx.lineWidth=1;ctx.stroke();ctx.beginPath();bands.forEach((b,i)=>i?ctx.lineTo(g.x(i/(bands.length-1)),g.y(b.median)):ctx.moveTo(g.x(0),g.y(b.median)));ctx.strokeStyle='#c1e59d';ctx.lineWidth=2;ctx.stroke();}
function commands(){const term=$('#command-input').value.toLowerCase();$('#command-results').innerHTML=views.filter(v=>v[1].toLowerCase().includes(term)).map(([v,t])=>`<button data-command="${v}">${t}<span style="float:right">↗</span></button>`).join('')}
function openCommand(){$('#command-dialog').showModal();$('#command-input').value='';commands();$('#command-input').focus()}
$('#command').onclick=openCommand;$('#command-input').oninput=commands;$('#command-results').onclick=ev=>{const b=ev.target.closest('[data-command]');if(b){location.hash=b.dataset.command;$('#command-dialog').close()}};document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key==='k'){ev.preventDefault();openCommand()}});
$('#notifications').onclick=()=>location.hash='markets';$('#logout').onclick=async()=>{await api('/logout',{});es?.close();$('#login').classList.remove('hidden');$('#access-token').value=''};
async function connected(){ $('#login').classList.add('hidden');await refresh();es?.close();es=new EventSource('/api/stream');es.addEventListener('update',()=>{if(!loading&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))refresh().catch(()=>{})});es.onerror=()=>$('#connection').textContent='Reconnecting…';es.onopen=()=>$('#connection').textContent='Local engine connected'; }
$('#login-form').onsubmit=async ev=>{ev.preventDefault();$('#login-error').textContent='';try{const result=await api('/login',{token:$('#access-token').value});csrf=result.csrf;$('#access-token').value='';await connected()}catch(err){$('#login-error').textContent=err.message}};
window.addEventListener('hashchange',()=>{if(state)render().catch(err=>toast(err.message,true))});let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if(state)render()},160)});
(async()=>{try{const session=await api('/session');csrf=session.csrf;await connected()}catch{}})();
